// Fractal Noise - wires the COLORS to the dock sliders (u_col1 / u_col2).
// Rebuilds the SAME fractal used in the displacement (same constant factors
// 2/4/8/16 and same t*0.5 scroll), so the color follows the relief:
// u_col2 in the valleys, u_col1 on the ridges.
// Runs INSIDE shadeSurface() -> no functions, everything inline. 't' and
// 'sys_noise' are available (t = texture clock; sys_noise lives in common.glsl).
// NB: CONSTANT factors and not NoiseW(), to avoid faulting the Adreno (see displacement).

float n1 = sys_noise(pModel * 2.0  + vec3(0.0, t * 0.5, 0.0));
float n2 = sys_noise(pModel * 4.0  + vec3(0.0, t * 0.5, 0.0));
float n3 = sys_noise(pModel * 8.0  + vec3(0.0, t * 0.5, 0.0));
float n4 = sys_noise(pModel * 16.0 + vec3(0.0, t * 0.5, 0.0));
float fractal = (n1 + n2 * 0.5 + n3 * 0.25 + n4 * 0.125) / 1.875;

// contrast: crisper ridges
float tcol = smoothstep(0.35, 0.75, fractal);

// DOCK COLORS: u_col2 = valleys, u_col1 = ridges
textureCol = mix(ubuf.u_col2, ubuf.u_col1, tcol);

