// Animated fractal (fbm, 4 octaves, lacunarity 2, gain 0.5).
// NB: we do NOT use NoiseW(). Cause confirmed via logcat + isolation test on the
// device (Galaxy Tab S9 Ultra, Adreno): NoiseW calls sys_noise(p * frequency) with
// 'frequency' growing at RUNTIME inside its loop; with a runtime argument the Adreno
// faults the GPU (gpuSnapshot -> context lost -> app killed). With CONSTANT
// frequencies the same noise runs fine. Here we unroll the 4 octaves by hand with
// constant factors (2,4,8,16): identical look, no fault.
float n1 = sys_noise(pModel * 2.0  + vec3(0.0, t * 0.5, 0.0));
float n2 = sys_noise(pModel * 4.0  + vec3(0.0, t * 0.5, 0.0));
float n3 = sys_noise(pModel * 8.0  + vec3(0.0, t * 0.5, 0.0));
float n4 = sys_noise(pModel * 16.0 + vec3(0.0, t * 0.5, 0.0));
float fractal = (n1 + n2 * 0.5 + n3 * 0.25 + n4 * 0.125) / 1.875;

// fractal in [0,1]. Center it between -0.5 and 0.5 and scale its strength.
float bump = (fractal - 0.5) * 0.15;

// Subtract the relief from the surface
d_surf -= bump;

// RAY MARCHING SAFETY TRICK:
// Multiplying the distance by 0.5 forces the rays to slow down, preventing them
// from passing through the fractal tips and becoming invisible!
d_surf *= 0.5;
